function closeCurrentModal(){const modalOverlay=document.querySelector('.modal-overlay');if(modalOverlay){document.body.removeChild(modalOverlay);}}
function openGenericCustomConditionModal(onCustomConditionSelect,title,showSelectedSection){if(document.querySelector('.modal-overlay')){return;}
const modalOverlay=document.createElement('div');modalOverlay.classList.add('modal-overlay');const modalContent=document.createElement('div');modalContent.classList.add('modal-content');const customConditionPanel=createGenericCustomConditionSelectionPanel(onCustomConditionSelect,title,showSelectedSection);modalContent.appendChild(customConditionPanel);modalOverlay.appendChild(modalContent);document.body.appendChild(modalOverlay);modalOverlay.addEventListener('mousedown',function(e){if(e.target===modalOverlay){document.body.removeChild(modalOverlay);}});}
function createGenericCustomConditionSelectionPanel(onCustomConditionSelect,title,showSelectedSection){const customConditionPanel=document.createElement('div');customConditionPanel.classList.add('builder-modal-panel');const header=document.createElement('div');header.classList.add('builder-modal-header');const headerTitle=document.createElement('span');headerTitle.textContent=title||'Select Custom Condition';headerTitle.style.flexGrow='1';const closeButton=document.createElement('button');closeButton.classList.add('close-window-button');closeButton.innerHTML='<i class="fa-solid fa-x"></i>';closeButton.addEventListener('click',function(){const modalOverlay=document.querySelector('.modal-overlay');if(modalOverlay){document.body.removeChild(modalOverlay);}});header.appendChild(headerTitle);header.appendChild(closeButton);const searchBarContainer=document.createElement('div');searchBarContainer.classList.add('builder-search-bar-container');const searchBar=document.createElement('input');searchBar.type='text';searchBar.classList.add('builder-search-bar');searchBar.placeholder='Search custom conditions...';searchBarContainer.appendChild(searchBar);const customConditionListContainer=document.createElement('div');customConditionListContainer.classList.add('modal-group-list');if(typeof window.customConditionTooltipGlobal==='undefined'||!Array.isArray(window.customConditionTooltipGlobal)){const noDataMessage=document.createElement('div');noDataMessage.textContent='No custom conditions available.';noDataMessage.style.textAlign='center';noDataMessage.style.padding='20px';noDataMessage.style.color='#999';customConditionListContainer.appendChild(noDataMessage);}else{const group=document.createElement('div');group.classList.add('modal-item-group');window.customConditionTooltipGlobal.forEach(function(customConditionData){const customCondition=document.createElement('div');customCondition.classList.add('builder-custom-condition-item');customCondition.setAttribute('data-custom-condition-name',customConditionData.name.toLowerCase());const img=document.createElement('img');img.src=customConditionData.image;img.alt=customConditionData.name;img.classList.add('custom-condition-icon','builder-custom-condition-icon');img.setAttribute('data-custom-condition-id',customConditionData.ID);const span=document.createElement('span');span.classList.add('builder-custom-condition-name');span.textContent=customConditionData.name;customCondition.appendChild(img);customCondition.appendChild(span);customCondition.addEventListener('click',function(){onCustomConditionSelect(customConditionData);});group.appendChild(customCondition);});customConditionListContainer.appendChild(group);}
let selectedCustomConditionsContainer;if(showSelectedSection){selectedCustomConditionsContainer=document.createElement('div');selectedCustomConditionsContainer.classList.add('selected-custom-conditions-container');updateSelectedCustomConditionsModalDisplay(selectedCustomConditionsContainer);}
customConditionPanel.appendChild(header);if(selectedCustomConditionsContainer){customConditionPanel.appendChild(selectedCustomConditionsContainer);}
customConditionPanel.appendChild(searchBarContainer);customConditionPanel.appendChild(customConditionListContainer);searchBar.addEventListener('input',function(){filterCustomConditionListInModal(searchBar.value,customConditionListContainer);});return customConditionPanel;}
function filterCustomConditionListInModal(query,customConditionListContainer){const lowerQuery=query.toLowerCase();const customConditionItems=customConditionListContainer.querySelectorAll('.builder-custom-condition-item');customConditionItems.forEach(function(customCondition){const customConditionName=customCondition.getAttribute('data-custom-condition-name').toLowerCase();if(customConditionName.includes(lowerQuery)){customCondition.style.display='';}else{customCondition.style.display='none';}});}
