const addStrongConditionButton=document.getElementById('add-strong-condition-button');const strongConditionMenu=document.getElementById('strong-condition-menu');if(addStrongConditionButton&&strongConditionMenu){let hoverTimeout;addStrongConditionButton.addEventListener('mouseenter',function(){clearTimeout(hoverTimeout);strongConditionMenu.style.display='block';});addStrongConditionButton.addEventListener('mouseleave',function(){hoverTimeout=setTimeout(()=>{strongConditionMenu.style.display='none';},200);});strongConditionMenu.addEventListener('mouseenter',function(){clearTimeout(hoverTimeout);});strongConditionMenu.addEventListener('mouseleave',function(){strongConditionMenu.style.display='none';});const menuOptions=strongConditionMenu.querySelectorAll('.menu-option');menuOptions.forEach(option=>{option.addEventListener('click',function(){const type=this.getAttribute('data-type');strongConditionMenu.style.display='none';openStrongConditionModal(type);});});}
function openStrongConditionModal(type){switch(type){case'Items':openStrongConditionItemModal();break;case'Augments':openStrongConditionAugmentModal();break;case'Openers':openStrongConditionOpenerModal();break;case'Custom':openStrongConditionCustomModal();break;}}
