function openStrongConditionCustomModal(){openGenericCustomConditionModal(function(customConditionData){console.log('🎯 Custom condition selected in modal:',customConditionData);if(customConditionData.linked_entity_type){closeCurrentModal();openLinkedEntitySelectionModal(customConditionData);}else{const tierModifier=1;console.log('🏷️ Using default tier modifier:',tierModifier);addStrongCondition('Custom',customConditionData,tierModifier);}},'Select Custom Conditions for Strong Conditions',true);}
