ment.createElement('img');img.src=entityData.icon;img.alt=entityData.name;img.classList.add('builder-entity-icon');if(customConditionData.linked_entity_type==='Champion'&&entityData.cost){const costClass=`cost${Math.min(Math.max(entityData.cost, 1), 6)}`;img.classList.add(costClass);}
