function getEntitiesByType(entityType){const entities=[];switch(entityType){case'Champion':if(window.championDataGlobal&&typeof window.championDataGlobal==='object'){Object.values(window.championDataGlobal).forEach(champion=>{if(champion&&champion.name&&champion.builderId){entities.push({type:'Champion',name:champion.name,icon:champion.tileIcon_url||'/wp-content/uploads/tooltip/icons/questionMark.svg',cost:champion.cost||1,apiName:champion.apiName});}});}
break;case'Item':if(window.itemTooltipDataGlobal&&typeof window.itemTooltipDataGlobal==='object'){Object.values(window.itemTooltipDataGlobal).forEach(item=>{if(item&&item.name){entities.push({type:'Item',name:item.name,icon:item.icon_url||'/wp-content/uploads/tooltip/icons/questionMark.svg',apiName:item.apiName});}});}
break;case'Trait':if(window.traitTooltipDataGlobal&&typeof window.traitTooltipDataGlobal==='object'){Object.values(window.traitTooltipDataGlobal).forEach(trait=>{if(trait&&trait.name){entities.push({type:'Trait',name:trait.name,icon:trait.icon_url||'/wp-content/uploads/tooltip/icons/questionMark.svg',apiName:trait.apiName});}});}
break;case'Augment':if(window.augmentTooltipDataGlobal&&typeof window.augmentTooltipDataGlobal==='object'){Object.values(window.augmentTooltipDataGlobal).forEach(augment=>{if(augment&&augment.name){entities.push({type:'Augment',name:augment.name,icon:augment.icon_url||'/wp-content/uploads/tooltip/icons/questionMark.svg',apiName:augment.apiName});}});}
break;case'Opener':if(window.openerDataGlobal&&typeof window.openerDataGlobal==='object'){Object.values(window.openerDataGlobal).forEach(setOpeners=>{if(setOpeners&&typeof setOpeners==='object'){Object.values(setOpeners).forEach(opener=>{if(opener&&opener.opener_name){entities.push({type:'Opener',name:opener.opener_name,icon:getOpenerIconUrlForLinkedEntity({id:opener.ID||opener.opener_name}),id:opener.ID||opener.opener_name});}});}});}
break;case'Composition':if(window.compositionDataGlobal&&typeof window.compositionDataGlobal==='object'){Object.values(window.compositionDataGlobal).forEach(composition=>{if(composition&&composition.name&&composition.ID){entities.push({type:'Composition',name:composition.name,icon:getCompositionIconUrlForLinkedEntity({id:composition.ID}),id:composition.ID});}});}
break;}
entities.sort((a,b)=>a.name.localeCompare(b.name));return entities;}
function filterEntityListInModal(query,entityListContainer){const lowerQuery=query.toLowerCase();const entityItems=entityListContainer.querySelectorAll('.builder-entity-item');entityItems.forEach(function(entityItem){const entityName=entityItem.getAttribute('data-entity-name').toLowerCase();if(entityName.includes(lowerQuery)){entityItem.style.display='';}else{entityItem.style.display='none';}});}
function addStrongConditionWithLinkedEntity(type,customConditionData,linkedEntityData,tierModifier){if(strongConditions.length>=50){showStrongConditionWarning('You can only have up to 50 strong conditions total.');return;}
const isDuplicate=strongConditions.some(condition=>condition.type==='Custom'&&condition.data.ID===customConditionData.ID&&condition.linkedEntity&&condition.linkedEntity.type===linkedEntityData.type&&(condition.linkedEntity.apiName===linkedEntityData.apiName||condition.linkedEntity.id===linkedEntityData.id));if(isDuplicate){showStrongConditionWarning('This custom condition with linked entity is already selected.');return;}
const newCondition={type:type,data:customConditionData,linkedEntity:linkedEntityData,tierModifier:tierModifier};strongConditions.push(newCondition);updateStrongConditionsDisplay();updateURLWithState();refreshModalSelectedSection(type);}
function addStrongCondition(type,data,tierModifier){if(strongConditions.length>=50){showStrongConditionWarning('You can only have up to 50 strong conditions total.');return;}
let isDuplicate=false;if(type==='Items'||type==='Augments'){isDuplicate=strongConditions.some(condition=>condition.type===type&&condition.data.apiName===data.apiName);}else if(type==='Openers'){isDuplicate=strongConditions.some(condition=>{if(condition.type!==type)return false;const conditionId=parseInt(condition.data.ID)||condition.data.ID;const dataId=parseInt(data.ID)||data.ID;if(conditionId&&dataId&&conditionId===dataId){return true;}
const conditionName=condition.data.name||condition.data.opener_name;const dataName=data.name||data.opener_name;if(conditionName&&dataName&&conditionName===dataName){return true;}
return false;});}else if(type==='Custom'){isDuplicate=strongConditions.some(condition=>{if(condition.type!==type||condition.data.ID!==data.ID){return false;}
if(!data.linked_entity_type){return true;}
if(!condition.linkedEntity){return true;}
return false;});}
if(isDuplicate){showStrongConditionWarning('This condition is already selected.');return;}
const newCondition={type:type,data:data,tierModifier:tierModifier};strongConditions.push(newCondition);updateStrongConditionsDisplay();updateURLWithState();refreshModalSelectedSection(type);}
function showStrongConditionWarning(message){const warning=document.createElement('div');warning.textContent=message;warning.style.cssText=`
          position: fixed;
          top: 50%;
          left: 50%;
          transform: translate(-50%, -50%);
          background-color: #ff4d4d;
          color: white;
          padding: 10px 20px;
          border-radius: 4px;
          z-index: 10000;
          font-weight: bold;
      `;document.body.appendChild(warning);setTimeout(()=>{document.body.removeChild(warning);},3000);}
function updateStrongConditionsDisplay(){const strongConditionsBody=document.getElementById('strong-conditions-body');if(!strongConditionsBody)return;const addButton=strongConditionsBody.querySelector('#add-strong-condition-button');strongConditionsBody.innerHTML='';if(addButton)strongConditionsBody.appendChild(addButton);if(strongConditions.length===0){return;}
const groupedConditions={};strongConditions.forEach(condition=>{const tier=condition.tierModifier;if(!groupedConditions[tier]){groupedConditions[tier]=[];}
groupedConditions[tier].push(condition);});const sortedTiers=Object.keys(groupedConditions).sort((a,b)=>parseInt(b)-parseInt(a));sortedTiers.forEach(tierModifier=>{const conditions=groupedConditions[tierModifier];const tierGroup=document.createElement('div');tierGroup.classList.add('condition-tier-group');const tierTitle=document.createElement('div');tierTitle.classList.add('condition-tier-title');tierTitle.innerHTML=getTierProgressionTitle(parseInt(tierModifier));const conditionsContainer=document.createElement('div');conditionsContainer.classList.add('condition-items');const sortedConditions=conditions.sort((a,b)=>{const typeOrder={'Custom':0,'Openers':1,'Items':2,'Augments':3};const aOrder=typeOrder[a.type]||999;const bOrder=typeOrder[b.type]||999;if(aOrder!==bOrder){return aOrder-bOrder;}
const aName=getConditionName(a);const bName=getConditionName(b);return aName.localeCompare(bName);});sortedConditions.forEach((condition)=>{const conditionElement=createStrongConditionElement(condition,tierModifier);conditionsContainer.appendChild(conditionElement);});tierGroup.appendChild(tierTitle);tierGroup.appendChild(conditionsContainer);strongConditionsBody.appendChild(tierGroup);});}
function getTierProgressionTitle(tierModifier){const tiers=['D','C','B','A','S','S+','OP'];const currentTierIndex=tiers.indexOf(baseTier);if(currentTierIndex===-1){return`+${tierModifier} Tier`;}
const newTierIndex=Math.min(currentTierIndex+tierModifier,tiers.length-1);const newTier=tiers[newTierIndex];return`+${tierModifier} Tier <span class="tier-dropdown-label" data-value="${baseTier}">${baseTier}</span> → <span class="tier-dropdown-label" data-value="${newTier}">${newTier}</span>`;}
