function removeStrongCondition(conditionToRemove){const isMatch=(condition)=>{if(condition.type!==conditionToRemove.type)return false;if(condition.type==='Items'||condition.type==='Augments'){return condition.data.apiName===conditionToRemove.data.apiName;}else if(condition.type==='Openers'){const conditionId=parseInt(condition.data.ID)||condition.data.ID;const removeId=parseInt(conditionToRemove.data.ID)||conditionToRemove.data.ID;if(conditionId&&removeId&&conditionId===removeId){return true;}
const conditionName=condition.data.name||condition.data.opener_name;const removeName=conditionToRemove.data.name||conditionToRemove.data.opener_name;if(conditionName&&removeName&&conditionName===removeName){return true;}
return false;}else if(condition.type==='Custom'){if(condition.data.ID!==conditionToRemove.data.ID){return false;}
if(condition.linkedEntity&&conditionToRemove.linkedEntity){return condition.linkedEntity.type===conditionToRemove.linkedEntity.type&&(condition.linkedEntity.apiName===conditionToRemove.linkedEntity.apiName||condition.linkedEntity.id===conditionToRemove.linkedEntity.id);}
if(condition.linkedEntity||conditionToRemove.linkedEntity){return false;}
return true;}
return false;};strongConditions=strongConditions.filter(condition=>!isMatch(condition));updateStrongConditionsDisplay();updateURLWithState();refreshModalSelectedSection(conditionToRemove.type);}
